use std::collections::HashMap;

/// 단어 앞뒤에서 떼어 낼 문장 부호. 단어 가운데 있는 것은 남긴다.
const PUNCTUATION: &str = "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~“”‘’…·";

/// Python 3.12(Unicode 15.0)의 str.lower() 가 바꾸지 않는데 Rust 쪽이 바꾸는 글자.
/// verify/lower_table.py 의 전수 비교로 확정한다.
fn is_lower_exception(c: char) -> bool {
    matches!(
        c,
        '\u{1C89}'
            | '\u{A7CB}'
            | '\u{A7CC}'
            | '\u{A7CE}'
            | '\u{A7D2}'
            | '\u{A7D4}'
            | '\u{A7DA}'
            | '\u{A7DC}'
            | '\u{10D50}'..='\u{10D65}'
            | '\u{16EA0}'..='\u{16EB8}'
    )
}

/// 문맥 판단에 영향을 주지 않는 자리 표시 글자(사설 영역)
const PLACEHOLDER: char = '\u{E000}';

pub struct Report {
    pub total_words: usize,
    pub unique_words: usize,
    pub top: Vec<(String, u64)>,
}

/// Python str.split() 이 공백으로 보는 글자(Py_UNICODE_ISSPACE)
pub fn is_py_space(c: char) -> bool {
    matches!(
        c,
        '\u{9}'..='\u{D}'
            | '\u{1C}'..='\u{1F}'
            | ' '
            | '\u{85}'
            | '\u{A0}'
            | '\u{1680}'
            | '\u{2000}'..='\u{200A}'
            | '\u{2028}'
            | '\u{2029}'
            | '\u{202F}'
            | '\u{205F}'
            | '\u{3000}'
    )
}

pub fn py_lower(word: &str) -> String {
    if !word.chars().any(is_lower_exception) {
        return word.to_lowercase();
    }
    // 예외 글자는 자리 표시 글자로 바꿔 소문자로 만든 뒤 순서대로 되돌린다
    let mut originals = Vec::new();
    let masked: String = word
        .chars()
        .map(|c| {
            if c == PLACEHOLDER || is_lower_exception(c) {
                originals.push(c);
                PLACEHOLDER
            } else {
                c
            }
        })
        .collect();
    let mut originals = originals.into_iter();
    masked
        .to_lowercase()
        .chars()
        .map(|c| {
            if c == PLACEHOLDER {
                originals.next().unwrap_or(c)
            } else {
                c
            }
        })
        .collect()
}

pub fn tokenize(text: &str) -> Vec<String> {
    text.split(is_py_space)
        .filter(|raw| !raw.is_empty())
        .map(|raw| py_lower(raw.trim_matches(|c| PUNCTUATION.contains(c))))
        .filter(|word| !word.is_empty())
        .collect()
}

pub fn count_words(words: &[String], top_n: usize) -> Report {
    let mut counter: HashMap<&str, u64> = HashMap::new();
    for word in words {
        *counter.entry(word.as_str()).or_insert(0) += 1;
    }
    let unique_words = counter.len();
    let mut ranked: Vec<(String, u64)> = counter
        .into_iter()
        .map(|(word, count)| (word.to_string(), count))
        .collect();
    ranked.sort_unstable_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.cmp(&b.0)));
    ranked.truncate(top_n.min(ranked.len()));
    Report {
        total_words: words.len(),
        unique_words,
        top: ranked,
    }
}

