pub fn display_name(arg: &std::ffi::OsStr) -> String {
    String::from_utf8_lossy(&os_to_bytes(arg)).into_owned()
}

/// `-h` 뒤에 붙은 값이 `h` 만으로 이뤄져야 도움말이 된다 (-hh)
fn short_help_ok(explicit: &Option<Vec<u8>>) -> bool {
    match explicit {
        None => true,
        Some(v) => !v.is_empty() && v.iter().all(|&b| b == b'h'),
    }
}

pub fn parse<I: IntoIterator<Item = OsString>>(args: I) -> Parsed {
    let args: Vec<Vec<u8>> = args.into_iter().map(|a| os_to_bytes(&a)).collect();
    let mut files: Vec<&[u8]> = Vec::new();
    let mut unrecognized = false;
    let mut top = DEFAULT_TOP;
    let mut json = false;
    let mut i = 0;
    while i < args.len() {
        let arg = args[i].as_slice();
        i += 1;
        if arg == b"--" {
            files.extend(args[i..].iter().map(Vec::as_slice));
            break;
        }
        let (opt, explicit) = match classify(arg) {
            Kind::Positional => {
                files.push(arg);
                continue;
            }
            Kind::Unknown => {
                unrecognized = true;
                continue;
            }
            Kind::Ambiguous => {
                let shown = String::from_utf8_lossy(arg);
                return Parsed::Usage(format!("ambiguous option: {shown}"));
            }
            Kind::Option(opt, explicit) => (opt, explicit),
        };
        match opt {
            Opt::Help => {
                let long = arg.starts_with(b"--");
                if (long && explicit.is_some()) || !short_help_ok(&explicit) {
                    return Parsed::Usage("ignored explicit argument".to_string());
                }
                return Parsed::Help;
            }
            Opt::Json => {
                if explicit.is_some() {
                    return Parsed::Usage("argument --json: ignored explicit argument".to_string());
                }
                json = true;
            }
            Opt::Top => {
                let value: &[u8] = match explicit.as_deref() {
                    Some(v) => v,
                    None => {
                        // nargs=None 의 패턴이 `-*A-*` 라서 `--top -- 5` 도 5 를 받는다.
                        // 그 뒤는 모두 위치 인자다
                        let after_dd = args.get(i).map(Vec::as_slice) == Some(b"--");
                        let at = if after_dd { i + 1 } else { i };
                        let usable = match args.get(at) {
                            Some(v) => after_dd || matches!(classify(v), Kind::Positional),
                            None => false,
                        };
                        if !usable {
                            return Parsed::Usage(
                                "argument --top: expected one argument".to_string(),
                            );
                        }
                        i = at + 1;
                        if after_dd {
                            files.extend(args[i..].iter().map(Vec::as_slice));
                            i = args.len();
                        }
                        args[at].as_slice()
                    }
                };
                match positive_int(value) {
                    Ok(n) => top = n,
                    Err(message) => return Parsed::Usage(message),
                }
            }
        }
    }

