/// argparse 의 `^-\d+$|^-\d*\.\d+$` (`$` 는 끝의 개행 하나도 허용)
fn looks_like_negative_number(arg: &[u8]) -> bool {
    let arg = arg.strip_suffix(b"\n").unwrap_or(arg);
    let Some(rest) = arg.strip_prefix(b"-") else {
