    }
    if let Some(eq) = arg.iter().position(|&b| b == b'=') {
        let (name, value) = (&arg[..eq], &arg[eq + 1..]);
        if name == b"-h" {
            return Kind::Option(Opt::Help, Some(value.to_vec()));
        }
        if let Some((_, opt)) = LONG_OPTIONS.iter().find(|(n, _)| *n == name) {
